import torch
import torch.nn as nn
import torch.nn.functional as F
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p2_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor shallow_wide_mlp_forward(
    torch::Tensor x,
    torch::Tensor w0, torch::Tensor b0,
    torch::Tensor w1, torch::Tensor b1,
    torch::Tensor w2, torch::Tensor b2
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("shallow_wide_mlp_forward", &shallow_wide_mlp_forward, "ShallowWideMLP forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>

// ---------------------------------------------------------------------------
// Fused bias-add + ReLU kernel (in-place on the output buffer)
// ---------------------------------------------------------------------------
__global__ void fused_bias_relu_kernel(float* __restrict__ out,
                                        const float* __restrict__ bias,
                                        int M, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = M * N;
    for (int i = idx; i < total; i += gridDim.x * blockDim.x) {
        int col = i % N;
        float v = out[i] + bias[col];
        out[i] = v > 0.f ? v : 0.f;
    }
}

// Bias-add only (final layer, no ReLU)
__global__ void fused_bias_kernel(float* __restrict__ out,
                                   const float* __restrict__ bias,
                                   int M, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = M * N;
    for (int i = idx; i < total; i += gridDim.x * blockDim.x) {
        out[i] += bias[i % N];
    }
}

// ---------------------------------------------------------------------------
// cuBLAS handle â lazily initialised, per-module singleton
// ---------------------------------------------------------------------------
static cublasHandle_t g_handle = nullptr;

static cublasHandle_t get_cublas_handle() {
    if (g_handle == nullptr) {
        cublasCreate(&g_handle);
    }
    // Bind to the current PyTorch CUDA stream so cuBLAS work is correctly ordered.
    cublasSetStream(g_handle, at::cuda::getCurrentCUDAStream());
    return g_handle;
}

// ---------------------------------------------------------------------------
// Main forward function
// ---------------------------------------------------------------------------
// x   : [M, K0]   w0 : [N0, K0]  b0 : [N0]
// h0  : [M, N0]   w1 : [N1, N0]  b1 : [N1]
// h1  : [M, N1]   w2 : [K2, N1]  b2 : [K2]
// out : [M, K2]
// Row-major A @ B^T = C  via cuBLAS column-major C^T = B @ A^T
//   cublasSgemm(handle, CUBLAS_OP_T, CUBLAS_OP_N, N, M, K, ...)
// ---------------------------------------------------------------------------
torch::Tensor shallow_wide_mlp_forward(
    torch::Tensor x,
    torch::Tensor w0, torch::Tensor b0,
    torch::Tensor w1, torch::Tensor b1,
    torch::Tensor w2, torch::Tensor b2
) {
    TORCH_CHECK(x.is_cuda() && x.dtype() == torch::kFloat32 && x.is_contiguous());

    const int M  = x.size(0);
    const int K0 = x.size(1);   // 16384
    const int N0 = w0.size(0);  // 32768
    const int N1 = w1.size(0);  // 32768
    const int K2 = w2.size(0);  // 16384

    // Allocate intermediates
    auto opts = x.options();
    torch::Tensor h0  = torch::empty({M, N0}, opts);
    torch::Tensor h1  = torch::empty({M, N1}, opts);
    torch::Tensor out = torch::empty({M, K2}, opts);

    cublasHandle_t handle = get_cublas_handle();
    const float alpha = 1.f, beta = 0.f;

    // Layer 0: h0 = x @ w0^T   [M,K0] @ [K0,N0] -> [M,N0]
    // cuBLAS col-major: C(N0,M) = w0(N0,K0) @ x^T(K0,M)
    //   => cublasSgemm(T, N, N0, M, K0, alpha, w0, K0, x, K0, beta, h0, N0)
    cublasStatus_t st;
    st = cublasSgemm(handle,
                     CUBLAS_OP_T, CUBLAS_OP_N,
                     N0, M, K0,
                     &alpha,
                     w0.data_ptr<float>(), K0,
                     x.data_ptr<float>(),  K0,
                     &beta,
                     h0.data_ptr<float>(), N0);
    TORCH_CHECK(st == CUBLAS_STATUS_SUCCESS, "cublasSgemm layer0 failed");

    // Fuse bias + ReLU for h0
    {
        int total = M * N0;
        int threads = 256;
        int blocks = std::min((total + threads - 1) / threads, 65535);
        fused_bias_relu_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            h0.data_ptr<float>(), b0.data_ptr<float>(), M, N0);
    }

    // Layer 1: h1 = h0 @ w1^T  [M,N0] @ [N0,N1] -> [M,N1]
    st = cublasSgemm(handle,
                     CUBLAS_OP_T, CUBLAS_OP_N,
                     N1, M, N0,
                     &alpha,
                     w1.data_ptr<float>(), N0,
                     h0.data_ptr<float>(), N0,
                     &beta,
                     h1.data_ptr<float>(), N1);
    TORCH_CHECK(st == CUBLAS_STATUS_SUCCESS, "cublasSgemm layer1 failed");

    // Fuse bias + ReLU for h1
    {
        int total = M * N1;
        int threads = 256;
        int blocks = std::min((total + threads - 1) / threads, 65535);
        fused_bias_relu_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            h1.data_ptr<float>(), b1.data_ptr<float>(), M, N1);
    }

    // Layer 2: out = h1 @ w2^T  [M,N1] @ [N1,K2] -> [M,K2]
    st = cublasSgemm(handle,
                     CUBLAS_OP_T, CUBLAS_OP_N,
                     K2, M, N1,
                     &alpha,
                     w2.data_ptr<float>(), N1,
                     h1.data_ptr<float>(), N1,
                     &beta,
                     out.data_ptr<float>(), K2);
    TORCH_CHECK(st == CUBLAS_STATUS_SUCCESS, "cublasSgemm layer2 failed");

    // Bias-add only for output layer (no ReLU)
    {
        int total = M * K2;
        int threads = 256;
        int blocks = std::min((total + threads - 1) / threads, 65535);
        fused_bias_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            out.data_ptr<float>(), b2.data_ptr<float>(), M, K2);
    }

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_layer_sizes, output_size):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                :param input_size: The number of input features
                :param hidden_layer_sizes: A list of ints containing the sizes of each hidden layer
                :param output_size: The number of output features
                """
        layers = []
        current_input_size = input_size
        for hidden_size in hidden_layer_sizes:
                    layers.append(nn.Linear(current_input_size, hidden_size))
                    layers.append(nn.ReLU())
                    current_input_size = hidden_size
        layers.append(nn.Linear(current_input_size, output_size))
        self.network = nn.Sequential(*layers)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        layers = list(self.network.children())
        use_fast_path = (
        x.is_cuda and
        x.dtype == torch.float32 and
        x.is_contiguous() and
        len(layers) == 5 and
        isinstance(layers[0], nn.Linear) and
        isinstance(layers[1], nn.ReLU) and
        isinstance(layers[2], nn.Linear) and
        isinstance(layers[3], nn.ReLU) and
        isinstance(layers[4], nn.Linear) and
        layers[0].in_features == 16384 and layers[0].out_features == 32768 and
        layers[2].in_features == 32768 and layers[2].out_features == 32768 and
        layers[4].in_features == 32768 and layers[4].out_features == 16384
        )
        if use_fast_path:
            ext = _stark_get_extension()
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return ext.shallow_wide_mlp_forward(
        x,
        layers[0].weight.contiguous(), layers[0].bias.contiguous(),
        layers[2].weight.contiguous(), layers[2].bias.contiguous(),
        layers[4].weight.contiguous(), layers[4].bias.contiguous()
        )
        return self.network(x)
        # <<<END_IMPROVE>>>

