// ---------------------------------------------------------------------------
// cuBLAS and cuBLASLt handle singletons
// ---------------------------------------------------------------------------
static cublasHandle_t g_handle = nullptr;
static cublasLtHandle_t g_lt_handle = nullptr;
static void* g_workspace = nullptr;
static size_t g_workspace_size = 32 * 1024 * 1024;

static cublasHandle_t get_cublas_handle() {
    if (g_handle == nullptr) {
        cublasCreate(&g_handle);
        cublasSetMathMode(g_handle, CUBLAS_TF32_TENSOR_OP_MATH);
    }
    cublasSetStream(g_handle, at::cuda::getDefaultCUDAStream());
    return g_handle;
