// TF32-optimized matmul helper using cuBLASLt
// Computes row-major C = A @ B^T with TF32 Tensor Core acceleration
// ---------------------------------------------------------------------------
static cublasStatus_t cublaslt_matmul_tf32(
    cublasLtHandle_t ltHandle,
    int M, int N, int K,
    const float* A, int ldA,
    const float* B, int ldB,
    float* C, int ldC,
    cudaStream_t stream
) {
    cublasLtMatmulDesc_t operationDesc = nullptr;
    cublasLtMatrixLayout_t Adesc = nullptr, Bdesc = nullptr, Cdesc = nullptr;
    cublasStatus_t status = CUBLAS_STATUS_SUCCESS;

    const float alpha = 1.0f, beta = 0.0f;

    status = cublasLtMatmulDescCreate(&operationDesc, CUBLAS_COMPUTE_32F_FAST_TF32, CUDA_R_32F);
    if (status != CUBLAS_STATUS_SUCCESS) goto cleanup;

    cublasOperation_t transA = CUBLAS_OP_N;
    cublasOperation_t transB = CUBLAS_OP_T;
    cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_TRANSA, &transA, sizeof(transA));
    cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_TRANSB, &transB, sizeof(transB));

    status = cublasLtMatrixLayoutCreate(&Adesc, CUDA_R_32F, M, K, ldA);
    if (status != CUBLAS_STATUS_SUCCESS) goto cleanup;
    status = cublasLtMatrixLayoutCreate(&Bdesc, CUDA_R_32F, N, K, ldB);
    if (status != CUBLAS_STATUS_SUCCESS) goto cleanup;
    status = cublasLtMatrixLayoutCreate(&Cdesc, CUDA_R_32F, M, N, ldC);
    if (status != CUBLAS_STATUS_SUCCESS) goto cleanup;

    cublasLtMatmulPreference_t preference = nullptr;
    status = cublasLtMatmulPreferenceCreate(&preference);
    if (status != CUBLAS_STATUS_SUCCESS) goto cleanup;
    cublasLtMatmulPreferenceSetAttribute(preference, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &g_workspace_size, sizeof(g_workspace_size));

    cublasLtMatmulHeuristicResult_t heuristicResult = {};
    int returnedResults = 0;
    status = cublasLtMatmulAlgoGetHeuristic(ltHandle, operationDesc, Adesc, Bdesc, Cdesc, Cdesc, preference, 1, &heuristicResult, &returnedResults);
    if (status != CUBLAS_STATUS_SUCCESS || returnedResults == 0) {
        if (preference) cublasLtMatmulPreferenceDestroy(preference);
        goto cleanup;
    }

    status = cublasLtMatmul(ltHandle, operationDesc,
                            &alpha, A, Adesc, B, Bdesc,
                            &beta, C, Cdesc, C, Cdesc,
                            &heuristicResult.algo, g_workspace, g_workspace_size, stream);

    if (preference) cublasLtMatmulPreferenceDestroy(preference);

cleanup:
    if (Cdesc) cublasLtMatrixLayoutDestroy(Cdesc);
    if (Bdesc) cublasLtMatrixLayoutDestroy(Bdesc);
    if (Adesc) cublasLtMatrixLayoutDestroy(Adesc);
    if (operationDesc) cublasLtMatmulDescDestroy(operationDesc);
    return status;
}

// ---------------------------------------------------------------------------
// Main forward function with TF32 fast path
// ---------------------------------------------------------------------------
torch::Tensor shallow_wide_mlp_forward(
    torch::Tensor x,
    torch::Tensor w0, torch::Tensor b0,
    torch::Tensor w1, torch::Tensor b1,
    torch::Tensor w2, torch::Tensor b2
