    const int K0 = x.size(1);
    const int N0 = w0.size(0);
    const int N1 = w1.size(0);
    const int K2 = w2.size(0);

    auto opts = x.options();
    torch::Tensor h0  = torch::empty({M, N0}, opts);
    torch::Tensor h1  = torch::empty({M, N1}, opts);
    torch::Tensor out = torch::empty({M, K2}, opts);

    cublasHandle_t handle = get_cublas_handle();
    cublasLtHandle_t ltHandle = get_cublaslt_handle();
    cudaStream_t stream = at::cuda::getDefaultCUDAStream();
    const float alpha = 1.f, beta = 0.f;

