// ---------------------------------------------------------------------------
// Helper: run one GEMM Y = X @ W^T using cuBLAS (row-major)
// X: [M, K]  W: [N, K]  Y: [M, N]
// cuBLAS is column-major, so we compute Y^T = W @ X^T
// ---------------------------------------------------------------------------
static void cublas_sgemm_nt(cublasHandle_t handle,
                             const float* X, const float* W, float* Y,
                             int M, int N, int K) {
    const float alpha = 1.f, beta = 0.f;
    // Y(M,N) = X(M,K) * W^T(K,N)
    // Col-major view: Y^T(N,M) = W(N,K) * X^T(K,M)
    cublasStatus_t st = cublasSgemm(handle,
        CUBLAS_OP_T,   // op(A) = W^T -> W is [N,K] col-major = [K,N] row-major
        CUBLAS_OP_N,   // op(B) = X
        M, N, K,       // m, n, k in col-major = rows of result, cols of result, inner
        &alpha,
        X, K,          // A (col-major [K,M]) = X row-major [M,K], lda=K
        W, K,          // B (col-major [K,N]) = W row-major [N,K], ldb=K
        &beta,
        Y, M);         // C (col-major [M,N]) = Y row-major [N,M]... wait
    // Correct formulation:
    // We want Y[M,N] = X[M,K] @ W[N,K]^T
    // cuBLAS col-major: C = op(A)*op(B), C is [m,n] col-major
    // Set: op(A)=W^T (so A=W [N,K] col-major, op=T -> [K,N] -> m=N side)
    // Actually simplest: treat all as col-major transposed
    // Y = X * W^T in row-major <==> Y^T = W * X^T in col-major
    // cublasSgemm(CUBLAS_OP_N, CUBLAS_OP_T, N, M, K, alpha, W, N, X, M, beta, Y, N)
    // but we already called above incorrectly; status ignored - we redo below
    (void)st;
}

// Correct GEMM wrapper
static void run_gemm(cublasHandle_t handle,
                     const float* X, const float* W, float* Y,
                     int M, int N, int K) {
    const float alpha = 1.f, beta = 0.f;
    // Y[M,N] = X[M,K] @ W^T[K,N]
    // Col-major: Y^T[N,M] = W[N,K] @ X^T[K,M]
    // cublasSgemm(handle, opA, opB, m, n, k, alpha, A, lda, B, ldb, beta, C, ldc)
    // where C[m,n]=op(A)[m,k]*op(B)[k,n] col-major
    // Set m=N, n=M, k=K, A=W (no-trans, col-major [N,K], lda=N), B=X (no-trans... X is [M,K] row-major = col-major [K,M], ldb=K -> need trans)
    // A=W col-major [N,K] lda=N, opA=N -> W[N,K]
    // B=X row-major [M,K] = col-major [K,M] ldb=K, opB=T -> X^T = [M,K] -> but we want X^T[K,M], opB=N gives [K,M] 
    // Actually: row-major X[M,K] stored as col-major X^T[K,M] with lda=M
    // Y^T[N,M] = W[N,K] (col-maj, lda=N) * X^T[K,M] (col-maj, lda=K... wait lda is leading dim)
    // X row-major [M,K]: element X[i,j] = X_ptr[i*K+j]. As col-major [K,M]: element [j,i] = ptr[j + i*K], leading dim = K (not M)
    // Hmm let me just use the standard formula:
    // C(m x n) = A(m x k) * B(k x n) all row-major
    // => cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, n, m, k, &alpha, B, n, A, k, &beta, C, n)
    // Here: Y(M x N) = X(M x K) * W^T(K x N)
    // A=X[M,K], B=W^T[K,N], C=Y[M,N]
    // => cublasSgemm(handle, N, N, N, M, K, alpha, W^T, N, X, K, beta, Y, N)
    // W^T is not materialized; W[N,K] row-major, W^T[K,N] row-major stored same memory
    // In col-major terms: W row-major [N,K] = W col-major [K,N], so W^T col-major = W col-major transposed = [N,K] col-major
    // Standard trick: Y = X * W^T row-major
    // => cublasSgemm(handle, CUBLAS_OP_T, CUBLAS_OP_N, N, M, K, &alpha, W, K, X, K, &beta, Y, N)
    cublasSgemm(handle,
        CUBLAS_OP_T, CUBLAS_OP_N,
        N, M, K,
        &alpha,
        W, K,   // W[N,K] row-major, treated as col-major [K,N], lda=K, with op=T gives [N,K]
        X, K,   // X[M,K] row-major, treated as col-major [K,M], lda=K, with op=N gives [K,M]
        &beta,
        Y, N);  // Y[M,N] row-major, treated as col-major [N,M], ldc=N
}

torch::Tensor shallow_wide_mlp_forward(
    torch::Tensor x,
    torch::Tensor w0, torch::Tensor b0,
    torch::Tensor w1, torch::Tensor b1,
    torch::Tensor w2, torch::Tensor b2) {

    TORCH_CHECK(x.is_cuda() && x.dtype() == torch::kFloat32, "x must be CUDA float32");
    TORCH_CHECK(x.dim() == 2 && x.is_contiguous(), "x must be 2D contiguous");

    int M  = x.size(0);
    int K0 = x.size(1);   // input_size
    int N0 = w0.size(0);  // hidden[0]
    int N1 = w1.size(0);  // hidden[1]
    int N2 = w2.size(0);  // output_size

