    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    cublasSetMathMode(handle, CUBLAS_TF32_TENSOR_OP_MATH);

    auto opts = x.options();
    auto hidden0 = torch::empty({M, N0}, opts);
    auto hidden1 = torch::empty({M, N1}, opts);
    auto out     = torch::empty({M, N2}, opts);

