    run_gemm(handle,
        x.data_ptr<float>(), w0.data_ptr<float>(), hidden0.data_ptr<float>(),
        M, N0, K0);
    // Fused bias + ReLU
    {
        int threads = 256;
        int blocks = std::min((M * N0 + threads - 1) / threads, 65535);
        fused_bias_relu_kernel<<<blocks, threads>>>(
            hidden0.data_ptr<float>(), b0.data_ptr<float>(), M, N0);
