    // Fused bias + ReLU
    {
        int threads = 256;
        int blocks = std::min((M * N1 + threads - 1) / threads, 65535);
        fused_bias_relu_kernel<<<blocks, threads>>>(
            hidden1.data_ptr<float>(), b1.data_ptr<float>(), M, N1);
    }

    // Layer 2: out = hidden1 @ w2^T
    run_gemm(handle,
        hidden1.data_ptr<float>(), w2.data_ptr<float>(), out.data_ptr<float>(),
        M, N2, N1);
    // Fused bias (no ReLU for final layer)
    {
        int threads = 256;
        int blocks = std::min((M * N2 + threads - 1) / threads, 65535);
        fused_bias_kernel<<<blocks, threads>>>(
            out.data_ptr<float>(), b2.data_ptr<float>(), M, N2);
    }

    // Restore default math mode
    cublasSetMathMode(handle, CUBLAS_DEFAULT_MATH);

    return out;
}
