    // Layer 2: C[M,K2]  = h1[M,N1] @ w2[K2,N1]^T
    // In column-major (cuBLAS native): C^T[N,M] = B[N,K] @ A^T[K,M]
    // We pass A (row-major MxK as col-major KxM), B (row-major NxK as col-major KxN)
    // and use CUBLAS_OP_N for B and CUBLAS_OP_T for A.
    // Equivalent: treat everything as col-major:
    //   C(N x M, col-major) = W(N x K, col-major, no-trans) @ X(K x M, col-major, no-trans)
    //   leading dims: ldW=N, ldX=K, ldC=N

    int Ms[3]  = {M,  M,  M};
    int Ns[3]  = {N0, N1, K2};
    int Ks[3]  = {K0, N0, N1};
    cublasLtEpilogue_t epis[3] = {
        CUBLASLT_EPILOGUE_RELU_BIAS,
        CUBLASLT_EPILOGUE_RELU_BIAS,
        CUBLASLT_EPILOGUE_BIAS
    };

    for (int l = 0; l < 3; l++) {
        int lM = Ms[l], lN = Ns[l], lK = Ks[l];

        if (cublasLtMatmulDescCreate(&g_lt.op_desc[l], CUBLAS_COMPUTE_32F, CUDA_R_32F)
                != CUBLAS_STATUS_SUCCESS) return false;

        cublasOperation_t opN = CUBLAS_OP_N;
        cublasLtMatmulDescSetAttribute(g_lt.op_desc[l],
            CUBLASLT_MATMUL_DESC_TRANSA, &opN, sizeof(opN));
        cublasLtMatmulDescSetAttribute(g_lt.op_desc[l],
            CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN));
        cublasLtMatmulDescSetAttribute(g_lt.op_desc[l],
            CUBLASLT_MATMUL_DESC_EPILOGUE, &epis[l], sizeof(epis[l]));

        // Layout: col-major convention
        // A matrix (weights) : lN x lK, col-major, ld=lN
        if (cublasLtMatrixLayoutCreate(&g_lt.layout_A[l], CUDA_R_32F, lN, lK, lN)
                != CUBLAS_STATUS_SUCCESS) return false;
