        if (cublasLtMatrixLayoutCreate(&g_lt.layout_C[l], CUDA_R_32F, lN, lM, lN)
                != CUBLAS_STATUS_SUCCESS) return false;

        // Heuristic search
        cublasLtMatmulPreference_t pref;
        if (cublasLtMatmulPreferenceCreate(&pref) != CUBLAS_STATUS_SUCCESS) return false;
        cublasLtMatmulPreferenceSetAttribute(pref,
            CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
            &g_lt.workspace_sz, sizeof(g_lt.workspace_sz));

        int returned = 0;
        cublasStatus_t hs = cublasLtMatmulAlgoGetHeuristics(
            g_lt.lt_handle,
            g_lt.op_desc[l],
            g_lt.layout_A[l],
            g_lt.layout_B[l],
            g_lt.layout_C[l],
            g_lt.layout_C[l],
            pref, 1,
            &g_lt.algo[l], &returned);
        cublasLtMatmulPreferenceDestroy(pref);
        if (hs == CUBLAS_STATUS_SUCCESS && returned > 0) {
            g_lt.algo_valid[l] = true;
        }
    }

    g_lt.init_ok = true;
    return true;
}

// ---------------------------------------------------------------------------
// Fallback: plain cuBLAS SGEMM + separate bias/relu kernels
// ---------------------------------------------------------------------------
static cublasHandle_t get_cublas_handle_fallback() {
    if (g_lt.bl_handle == nullptr) {
        cublasCreate(&g_lt.bl_handle);
    }
    cublasSetStream(g_lt.bl_handle, at::cuda::getDefaultCUDAStream());
    return g_lt.bl_handle;
}

static void run_gemm_fallback(
    cublasHandle_t handle,
    int N, int M, int K,
    const float* W, const float* A, float* C
) {
    const float alpha = 1.f, beta = 0.f;
    cublasSgemm(handle, CUBLAS_OP_T, CUBLAS_OP_N,
                N, M, K, &alpha, W, K, A, K, &beta, C, N);
}

// ---------------------------------------------------------------------------
// Main forward function
// ---------------------------------------------------------------------------
torch::Tensor shallow_wide_mlp_forward(
    torch::Tensor x,
    torch::Tensor w0, torch::Tensor b0,
    torch::Tensor w1, torch::Tensor b1,
    torch::Tensor w2, torch::Tensor b2
