    const int M  = (int)x.size(0);
    const int K0 = (int)x.size(1);
    const int N0 = (int)w0.size(0);
    const int N1 = (int)w1.size(0);
    const int K2 = (int)w2.size(0);

    auto opts = x.options();
    torch::Tensor h0  = torch::empty({M, N0}, opts);
    torch::Tensor h1  = torch::empty({M, N1}, opts);
    torch::Tensor out = torch::empty({M, K2}, opts);

    cudaStream_t stream = at::cuda::getDefaultCUDAStream();

    bool use_lt = init_lt_state(M, K0, N0, N1, K2);

    if (use_lt) {
        // Rebind stream
        cublasLtHandle_t lth = g_lt.lt_handle;
        const float alpha = 1.f, beta = 0.f;

        const float* bias_ptrs[3] = {
            b0.data_ptr<float>(),
            b1.data_ptr<float>(),
            b2.data_ptr<float>()
        };
        float* out_ptrs[3] = {
            h0.data_ptr<float>(),
            h1.data_ptr<float>(),
            out.data_ptr<float>()
