                lth,
                g_lt.op_desc[l],
                &alpha,
                w_ptrs[l],   g_lt.layout_A[l],
                in_ptrs[l],  g_lt.layout_B[l],
                &beta,
                out_ptrs[l], g_lt.layout_C[l],
                out_ptrs[l], g_lt.layout_C[l],
                g_lt.algo_valid[l] ? &g_lt.algo[l].algo : nullptr,
                g_lt.workspace, g_lt.workspace_sz,
                stream);
