    // Fallback path: plain cublasSgemm + separate pointwise kernels
    // ---------------------------------------------------------------------------
    cublasHandle_t handle = get_cublas_handle_fallback();

    run_gemm_fallback(handle, N0, M, K0, w0.data_ptr<float>(), x.data_ptr<float>(), h0.data_ptr<float>());
    {
        int total = M * N0;
        int threads = 256;
        int blocks = std::min((total + threads - 1) / threads, 65535);
        fused_bias_relu_kernel<<<blocks, threads, 0, stream>>>(
            h0.data_ptr<float>(), b0.data_ptr<float>(), M, N0);
