    run_gemm_fallback(handle, N1, M, N0, w1.data_ptr<float>(), h0.data_ptr<float>(), h1.data_ptr<float>());
    {
        int total = M * N1;
        int threads = 256;
        int blocks = std::min((total + threads - 1) / threads, 65535);
        fused_bias_relu_kernel<<<blocks, threads, 0, stream>>>(
            h1.data_ptr<float>(), b1.data_ptr<float>(), M, N1);
    }

    run_gemm_fallback(handle, K2, M, N1, w2.data_ptr<float>(), h1.data_ptr<float>(), out.data_ptr<float>());
    {
        int total = M * K2;
        int threads = 256;
