// ---------------------------------------------------------------------------
// Fused bias-add only kernel (final layer, no ReLU)
// Used as fallback when cuBLASLt epilogue is unavailable
// ---------------------------------------------------------------------------
__global__ void fused_bias_kernel(float* __restrict__ out,
                                   const float* __restrict__ bias,
                                   int M, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = M * N;
    for (int i = idx; i < total; i += gridDim.x * blockDim.x) {
        out[i] += bias[i % N];
    }
}

__global__ void fused_bias_relu_kernel(float* __restrict__ out,
                                        const float* __restrict__ bias,
                                        int M, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = M * N;
    for (int i = idx; i < total; i += gridDim.x * blockDim.x) {
        int col = i % N;
        float v = out[i] + bias[col];
        out[i] = v > 0.f ? v : 0.f;
    }
}

// ---------------------------------------------------------------------------
// cuBLASLt state - lazily initialised, per-module singleton
// ---------------------------------------------------------------------------
struct LtState {
    cublasLtHandle_t lt_handle = nullptr;
    cublasHandle_t   bl_handle = nullptr;

    // Per-layer cached descriptors (layer 0, 1, 2)
    cublasLtMatmulDesc_t   op_desc[3]  = {nullptr, nullptr, nullptr};
    cublasLtMatrixLayout_t layout_A[3] = {nullptr, nullptr, nullptr};
    cublasLtMatrixLayout_t layout_B[3] = {nullptr, nullptr, nullptr};
    cublasLtMatrixLayout_t layout_C[3] = {nullptr, nullptr, nullptr};
    cublasLtMatmulHeuristicResult_t algo[3];
    bool algo_valid[3] = {false, false, false};

    // Workspace
    void*  workspace     = nullptr;
    size_t workspace_sz  = 0;

    bool init_ok = false;
};

static LtState g_lt;

static bool init_lt_state(int M, int K0, int N0, int N1, int K2) {
    if (g_lt.init_ok) return true;

    if (cublasLtCreate(&g_lt.lt_handle) != CUBLAS_STATUS_SUCCESS) return false;
    if (cublasCreate(&g_lt.bl_handle)   != CUBLAS_STATUS_SUCCESS) return false;

    // Allocate workspace (32 MB is typically enough for good algorithm selection)
    g_lt.workspace_sz = 32 * 1024 * 1024;
    if (cudaMalloc(&g_lt.workspace, g_lt.workspace_sz) != cudaSuccess) {
        g_lt.workspace_sz = 0;
        g_lt.workspace = nullptr;
    }

