        cublasLtMatmulDescSetAttribute(g_lt.op_desc[l],
            CUBLASLT_MATMUL_DESC_TRANSA, &opN, sizeof(opN));
        cublasLtMatmulDescSetAttribute(g_lt.op_desc[l],
            CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN));
        cublasLtMatmulDescSetAttribute(g_lt.op_desc[l],
            CUBLASLT_MATMUL_DESC_EPILOGUE, &epis[l], sizeof(epis[l]));

        // Layout: col-major convention
        // A matrix (weights) : lN x lK, col-major, ld=lN
        if (cublasLtMatrixLayoutCreate(&g_lt.layout_A[l], CUDA_R_32F, lN, lK, lN)
