// ---------------------------------------------------------------------------
struct LtLayerState {
    cublasLtMatmulDesc_t   op_desc  = nullptr;
    cublasLtMatrixLayout_t layout_A = nullptr;  // weight [N, K] row-major
    cublasLtMatrixLayout_t layout_B = nullptr;  // input  [M, K] row-major
    cublasLtMatrixLayout_t layout_C = nullptr;  // output [M, N] row-major
    cublasLtMatmulAlgo_t   algo;
    bool                   algo_valid = false;
    size_t                 workspace_size = 0;
};

struct LtState {
    cublasLtHandle_t lt_handle = nullptr;
    cublasHandle_t   bl_handle = nullptr;
