static bool init_lt_layer(
    LtLayerState& ls,
    cublasLtHandle_t lt_handle,
    int M, int N, int K,
    cublasLtEpilogue_t epilogue,
    const float* bias_ptr,
    void* workspace, size_t ws_size)
{
