    if (ls.op_desc)   { cublasLtMatmulDescDestroy(ls.op_desc);   ls.op_desc   = nullptr; }
    if (ls.layout_A)  { cublasLtMatrixLayoutDestroy(ls.layout_A); ls.layout_A  = nullptr; }
    if (ls.layout_B)  { cublasLtMatrixLayoutDestroy(ls.layout_B); ls.layout_B  = nullptr; }
    if (ls.layout_C)  { cublasLtMatrixLayoutDestroy(ls.layout_C); ls.layout_C  = nullptr; }
