    // We use: Y[M,N] = X[M,K] * W^T[K,N]
    // In cuBLASLt row-major: opA=CUBLAS_OP_N on X[M,K], opB=CUBLAS_OP_T on W[N,K]
    // Result C[M,N] stored row-major
    if (cublasLtMatmulDescCreate(&ls.op_desc, CUBLAS_COMPUTE_32F, CUDA_R_32F) != CUBLAS_STATUS_SUCCESS)
        return false;

