    if (cublasLtMatmulDescSetAttribute(ls.op_desc, CUBLASLT_MATMUL_DESC_TRANSB, &opB, sizeof(opB)) != CUBLAS_STATUS_SUCCESS) return false;

    if (cublasLtMatmulDescSetAttribute(ls.op_desc, CUBLASLT_MATMUL_DESC_EPILOGUE, &epilogue, sizeof(epilogue)) != CUBLAS_STATUS_SUCCESS) return false;
