    // A = X [M, K] row-major, ld = K
    if (cublasLtMatrixLayoutCreate(&ls.layout_A, CUDA_R_32F, M, K, K) != CUBLAS_STATUS_SUCCESS) return false;
    // B = W [N, K] row-major, ld = K (opB=T means cuBLASLt sees it as K x N)
    if (cublasLtMatrixLayoutCreate(&ls.layout_B, CUDA_R_32F, N, K, K) != CUBLAS_STATUS_SUCCESS) return false;
