        w2.data_ptr<float>(), h1.data_ptr<float>(), out.data_ptr<float>());
    {
        int total = M * K2;
        int threads = 256;
        int blocks = std::min((total + threads - 1) / threads, 65535);
        fused_bias_kernel<<<blocks, threads, 0, stream>>>(
            out.data_ptr<float>(), b2.data_ptr<float>(), M, K2);
    }

    return out;
}
